{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/2"],
      "relevance": "내담자가 '들러리'라는 말에 유난히 반응하는 것은, 자신이 가족의 중심에서 모든 것을 결정하고 책임져온 특별한 존재라는 과대적 자기상이 부정당했기 때문. 어머니로부터 '급이 다르다'는 메시지를 반복적으로 받아온 성장 배경이 이 신념의 뿌리이며, 아내의 별거 통보 상황에서 '들러리'라는 표현이 그 신념을 정면으로 위협하고 있음."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/2"],
      "relevance": "내담자는 본인이主动적으로 해온 일(돈, 학원, 대소사 결정)이 부수적이라고 불리는 것을 '아니다'라고 거부하며, 이는 '나는 특별하므로 보통의 대우를 받아서는 안 된다'는 핵심 신념이 작동하고 있음을 보여줌. 상담사의 '중심 위치가 부정당한 느낌'에 대한 질문이 바로 이 신념과 맞닿아 있음."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '매달 돈, 학원, 대소사를 제가 다 결정하고 책임져왔다'고 강조하는 것은 '내 판단이 기준이 되어야 한다'는 규칙이 작동하는 모습. 아내가 그 결정들을 '들러리'로 재정의한 것이 이 규칙을 위반한 것으로 느껴지는 것."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data", "/situations/2"],
      "relevance": "아내가 자신을 '들러리'로 부른 것은 내담자에게 '보통 사람들과 같은 취급'을 받는 사건으로, 이 가정의 부정적 조건('그저 그런 사람으로 전락')이 활성화된 상황. 억울함 밑에 있는 '모르는 감정'이 바로 이 전락에 대한 불안일 가능성이 있음."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/2"],
      "relevance": "내담자는 자신이 성과(경제적 기여, 결정권 행사)를 냈으므로 가족이 자신의 방식을 따르고 자신의 위치를 인정해야 한다고 기대함. 아내가 이를 인정하지 않은 것이 긍정적 가정이 깨진 사건에 해당."
    }
  ]
}

